import { BRAND_NAME } from './brand/brand.js'
import { meta as metaCopy, product, share } from './content/copy.js'
import { DEFAULT_SITE_URL, PRODUCT_PATH, ROUTES, findRoute } from './routes.js'

// Share image generated by `npm run brand:images` (scripts/generate-brand-images.mjs).
export const OG_IMAGE_PATH = '/og-image.png'
export const OG_IMAGE_WIDTH = 1200
export const OG_IMAGE_HEIGHT = 630

// Returns the canonical origin (no trailing slash). Falls back to the default when
// SITE_URL is unset or not an absolute http(s) URL, so a bad env value can't leak
// odd URLs into robots.txt or the sitemap.
export function resolveSiteUrl(value) {
  if (!value || typeof value !== 'string') return DEFAULT_SITE_URL
  try {
    const url = new URL(value.trim())
    if (url.protocol !== 'https:' && url.protocol !== 'http:') return DEFAULT_SITE_URL
    return url.origin
  } catch {
    return DEFAULT_SITE_URL
  }
}

export function absoluteUrl(siteUrl, path) {
  return path === '/' ? `${siteUrl}/` : `${siteUrl}${path}`
}

export function buildRobotsTxt(siteUrl) {
  return ['User-agent: *', 'Allow: /', 'Disallow: /api/', '', `Sitemap: ${siteUrl}/sitemap.xml`, ''].join('\n')
}

export function buildSitemapXml(siteUrl) {
  const urls = ROUTES.filter((route) => route.inSitemap)
    .map((route) => `  <url>\n    <loc>${absoluteUrl(siteUrl, route.path)}</loc>\n  </url>`)
    .join('\n')
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>\n`
}

export function organizationJsonLd(siteUrl) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Organization',
    name: BRAND_NAME,
    url: absoluteUrl(siteUrl, '/'),
    logo: absoluteUrl(siteUrl, '/apple-touch-icon.png'),
  }
}

// Coming soon: deliberately no `offers` / price until checkout ships.
export function productJsonLd(siteUrl) {
  return {
    '@context': 'https://schema.org',
    '@type': 'Product',
    name: product.name,
    description: metaCopy.product.description,
    url: absoluteUrl(siteUrl, PRODUCT_PATH),
    image: absoluteUrl(siteUrl, OG_IMAGE_PATH),
    brand: { '@type': 'Brand', name: BRAND_NAME },
  }
}

// Everything that goes in <head> for one path. Unknown paths get the 404 page's tags with
// noindex; their canonical points at home since a 404 has no URL of its own to claim.
export function pageMeta(pathname, siteUrl = DEFAULT_SITE_URL) {
  const route = findRoute(pathname)
  const copy = metaCopy[route ? route.metaKey : 'notFound']
  const title = route?.path === '/' ? copy.title : `${copy.title} | ${BRAND_NAME}`
  const jsonLd = []
  if (route?.path === '/') jsonLd.push(organizationJsonLd(siteUrl))
  if (route?.path === PRODUCT_PATH) jsonLd.push(productJsonLd(siteUrl))
  return {
    title,
    description: copy.description,
    canonical: absoluteUrl(siteUrl, route ? route.path : '/'),
    image: absoluteUrl(siteUrl, OG_IMAGE_PATH),
    imageAlt: share.imageAlt,
    noindex: !route,
    jsonLd,
  }
}

// Head elements as plain descriptors, so the build (HTML string) and the browser (DOM)
// render exactly the same tags. Every managed element carries data-seo.
export function headTags(meta) {
  const tags = [
    { tag: 'meta', attrs: { name: 'description', content: meta.description } },
    { tag: 'link', attrs: { rel: 'canonical', href: meta.canonical } },
  ]
  if (meta.noindex) tags.push({ tag: 'meta', attrs: { name: 'robots', content: 'noindex' } })
  const og = {
    'og:type': 'website',
    'og:site_name': BRAND_NAME,
    'og:locale': 'en_US',
    'og:title': meta.title,
    'og:description': meta.description,
    'og:url': meta.canonical,
    'og:image': meta.image,
    'og:image:type': 'image/png',
    'og:image:width': String(OG_IMAGE_WIDTH),
    'og:image:height': String(OG_IMAGE_HEIGHT),
    'og:image:alt': meta.imageAlt,
  }
  for (const [property, content] of Object.entries(og)) tags.push({ tag: 'meta', attrs: { property, content } })
  const twitter = {
    'twitter:card': 'summary_large_image',
    'twitter:title': meta.title,
    'twitter:description': meta.description,
    'twitter:image': meta.image,
    'twitter:image:alt': meta.imageAlt,
  }
  for (const [name, content] of Object.entries(twitter)) tags.push({ tag: 'meta', attrs: { name, content } })
  for (const data of meta.jsonLd) {
    tags.push({ tag: 'script', attrs: { type: 'application/ld+json' }, text: JSON.stringify(data) })
  }
  return tags
}

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('"', '&quot;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
}

// Keeps "</script>" (or any tag) inside JSON-LD from closing the script element.
function escapeScriptText(text) {
  return text.replaceAll('<', '\\u003c')
}

export function renderHeadHtml(meta) {
  const lines = [`<title>${escapeHtml(meta.title)}</title>`]
  for (const { tag, attrs, text } of headTags(meta)) {
    const attrText = Object.entries(attrs)
      .map(([key, value]) => ` ${key}="${escapeHtml(value)}"`)
      .join('')
    if (tag === 'script') lines.push(`<script data-seo${attrText}>${escapeScriptText(text)}</script>`)
    else lines.push(`<${tag} data-seo${attrText} />`)
  }
  return lines.join('\n    ')
}

// Client-side navigation: swap every data-seo element for the new page's set.
export function applyHeadMeta(doc, meta) {
  doc.title = meta.title
  for (const el of doc.head.querySelectorAll('[data-seo]')) el.remove()
  for (const { tag, attrs, text } of headTags(meta)) {
    const el = doc.createElement(tag)
    el.setAttribute('data-seo', '')
    for (const [key, value] of Object.entries(attrs)) el.setAttribute(key, value)
    if (text !== undefined) el.textContent = text
    doc.head.appendChild(el)
  }
}

// Markers in index.html between which the build writes each page's head tags.
export const SEO_START = '<!-- seo:start -->'
export const SEO_END = '<!-- seo:end -->'

export function injectHead(html, meta) {
  const start = html.indexOf(SEO_START)
  const end = html.indexOf(SEO_END)
  if (start === -1 || end === -1 || end < start) throw new Error('index.html is missing the seo:start/seo:end markers')
  return `${html.slice(0, start + SEO_START.length)}\n    ${renderHeadHtml(meta)}\n    ${html.slice(end)}`
}
